test "can't be chained" {
    const stones = &[_][2]u3{ [2]u3{ 1, 2 }, [2]u3{ 4, 1 }, [2]u3{ 2, 3 } };
    try testing.expect(!try dominoes.canChain(testing.allocator, stones));
}

