test "disconnected - double loop" {
    const stones = &[_][2]u3{ [2]u3{ 1, 2 }, [2]u3{ 2, 1 }, [2]u3{ 3, 4 }, [2]u3{ 4, 3 } };
    try testing.expect(!try dominoes.canChain(testing.allocator, stones));
